// ===== Stage 2: rich virtualization detail (durable tables) =====
func (q *Queries) UpsertDatastore(ctx context.Context, arg UpsertDatastoreParams) error {
	_, err := q.db.Exec(ctx, upsertDatastore,
		arg.HostDeviceID,
		arg.Name,
		arg.Type,
		arg.CapacityBytes,
		arg.FreeBytes,
	)
	return err
}

